import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import networkx as nx
import numpy as np
from collections import defaultdict

from Calc_PerGraph import enumerate_blocking_sequences

#Note: The following code was complety generated by ClaudeCode, because is only used for visualization, and is not part of the main algorithm. It is not tested, and may contain errors. Use at your own risk.


def visualize_blocking_limits(adjacency_matrix, graph_title="Original graph"):
    """
    Plot the graph and, for each distinct blocking limit (final saturated
    state) reachable by the process, a panel with the selected nodes
    highlighted in red.

    Parameters:
        adjacency_matrix: n x n list of lists (graph adjacency matrix)
        graph_title: title used for the original graph plot
    """
    n = len(adjacency_matrix)
    sequences = enumerate_blocking_sequences(adjacency_matrix)

    # Build the graph with NetworkX.
    graph = nx.Graph()
    graph.add_nodes_from(range(n))
    for i in range(n):
        for j in range(i + 1, n):
            if adjacency_matrix[i][j] != 0:
                graph.add_edge(i, j)

    # Fixed layout shared by all subplots (spring layout with fixed seed
    # for reproducibility; circular layout for very small graphs).
    if n <= 2:
        positions = nx.circular_layout(graph)
    else:
        positions = nx.spring_layout(graph, seed=42, k=2.5 / np.sqrt(n))

    # Group sequences by final blocking state.
    state_info = defaultdict(lambda: {"probability": 0.0, "sequences": []})
    for sequence, probability, state in sequences:
        state_info[state]["probability"] += probability
        state_info[state]["sequences"].append(sequence)

    limits = list(state_info.items())  # [(state, info), ...]
    num_limits = len(limits)

    # Color palette.
    COLOR_SELECTED = "#e53935"          # bright red: chosen node
    COLOR_BLOCKED = "#ffcdd2"           # light red: blocked neighbor, not chosen
    COLOR_FREE = "#e8f5e9"              # soft green: free node
    COLOR_BORDER_SELECTED = "#b71c1c"
    COLOR_BORDER_FREE = "#388e3c"
    COLOR_EDGE = "#90a4ae"
    COLOR_EDGE_SELECTED = "#ef9a9a"     # edges between two selected nodes

    def node_colors(state):
        """Return fill and border colors per node for a given final state."""
        selected = set(i for i, v in enumerate(state) if v == 1)

        # Blocked nodes = neighbors of selected nodes that were not selected.
        blocked = set()
        for i in selected:
            for j in range(n):
                if adjacency_matrix[i][j] != 0 and j not in selected:
                    blocked.add(j)

        fills, borders = [], []
        for i in range(n):
            if i in selected:
                fills.append(COLOR_SELECTED)
                borders.append(COLOR_BORDER_SELECTED)
            elif i in blocked:
                fills.append(COLOR_BLOCKED)
                borders.append("#e57373")
            else:
                fills.append(COLOR_FREE)
                borders.append(COLOR_BORDER_FREE)
        return fills, borders

    def edge_colors(state):
        """Edges between two selected nodes are highlighted differently."""
        selected = set(i for i, v in enumerate(state) if v == 1)
        colors = []
        for u, v in graph.edges():
            if u in selected and v in selected:
                colors.append(COLOR_EDGE_SELECTED)
            else:
                colors.append(COLOR_EDGE)
        return colors

    # Main figure: original graph.
    fig0, ax0 = plt.subplots(figsize=(5, 4))
    fig0.patch.set_facecolor("#1a1a2e")
    ax0.set_facecolor("#1a1a2e")

    nx.draw_networkx_edges(graph, positions, ax=ax0,
                            edge_color="#546e7a", width=2, alpha=0.8)
    nx.draw_networkx_nodes(graph, positions, ax=ax0,
                            node_color="#42a5f5",
                            node_size=600,
                            edgecolors="#1565c0", linewidths=2.5)
    nx.draw_networkx_labels(graph, positions, ax=ax0,
                             labels={i: str(i + 1) for i in range(n)},
                             font_color="white", font_size=11, font_weight="bold")
    ax0.set_title(graph_title, color="white", fontsize=13,
                  fontweight="bold", pad=10)
    ax0.axis("off")
    fig0.tight_layout()
    plt.show()
    print(f"\n  Nodes: {n}   |   Edges: {graph.number_of_edges()}")
    print(f"  Distinct blocking limits: {num_limits}\n")

    # Panel with all blocking limits.
    cols = min(4, num_limits)
    rows = int(np.ceil(num_limits / cols))

    fig, axes = plt.subplots(rows, cols, figsize=(cols * 3.8, rows * 3.6))
    fig.patch.set_facecolor("#0d1117")

    # Flatten axes for uniform indexing.
    if num_limits == 1:
        axes = [axes]
    else:
        axes = np.array(axes).flatten()

    for idx, (state, info) in enumerate(limits):
        ax = axes[idx]
        ax.set_facecolor("#161b22")

        fills, borders = node_colors(state)
        current_edge_colors = edge_colors(state)

        nx.draw_networkx_edges(graph, positions, ax=ax,
                                edge_color=current_edge_colors, width=2, alpha=0.85)
        nx.draw_networkx_nodes(graph, positions, ax=ax,
                                node_color=fills,
                                node_size=520,
                                edgecolors=borders,
                                linewidths=2.2)
        nx.draw_networkx_labels(graph, positions, ax=ax,
                                 labels={i: str(i + 1) for i in range(n)},
                                 font_color="#eceff1",
                                 font_size=10, font_weight="bold")

        k = sum(state)
        probability = info["probability"]
        num_sequences = len(info["sequences"])

        ax.set_title(
            f"Blocking limit #{idx + 1}   k={k}",
            color="#90caf9", fontsize=10, fontweight="bold", pad=6
        )

        state_str = "".join(str(v) for v in state)
        ax.text(0.5, -0.08,
                f"State: [{state_str}]",
                transform=ax.transAxes,
                ha="center", va="top",
                color="#b0bec5", fontsize=8, family="monospace")
        ax.text(0.5, -0.16,
                f"P = {probability:.5f}   ({num_sequences} seq.)",
                transform=ax.transAxes,
                ha="center", va="top",
                color="#a5d6a7", fontsize=8)
        ax.axis("off")

    # Hide unused subplots.
    for idx in range(num_limits, len(axes)):
        axes[idx].set_visible(False)

    legend_patches = [
        mpatches.Patch(color=COLOR_SELECTED, label="Selected (in IS)"),
        mpatches.Patch(color=COLOR_BLOCKED, label="Blocked (neighbor)"),
        mpatches.Patch(color=COLOR_FREE, label="Free"),
    ]
    fig.legend(handles=legend_patches, loc="lower center",
               ncol=3, frameon=False,
               fontsize=10, labelcolor="white",
               bbox_to_anchor=(0.5, 0.01))

    fig.suptitle(
        f"All blocking limits — {num_limits} distinct",
        color="white", fontsize=14, fontweight="bold", y=1.01
    )
    fig.tight_layout(rect=[0, 0.06, 1, 1])
    plt.show()


